package com.schoolmanagement.notification;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.Map;
@Component @ConditionalOnProperty(name="app.sms.provider",havingValue="arkesel") public class ArkeselSmsGateway implements SmsGateway {private final RestClient client;private final String key,sender; public ArkeselSmsGateway(@Value("${app.sms.arkesel.base-url}")String url,@Value("${app.sms.arkesel.api-key}")String key,@Value("${app.sms.arkesel.sender-id}")String sender){this.client=RestClient.builder().baseUrl(url).build();this.key=key;this.sender=sender;} public String send(String phone,String message){if(key==null||key.isBlank())throw new IllegalStateException("ARKESEL_API_KEY is not configured");var response=client.post().contentType(MediaType.APPLICATION_JSON).header("api-key",key).body(Map.of("sender",sender,"message",message,"recipients",new String[]{phone})).retrieve().body(Map.class);return response==null?"ARKESEL-ACCEPTED":String.valueOf(response.getOrDefault("message_id","ARKESEL-ACCEPTED"));}}
